(async()=>{
 const {mountPlus}=await import('/plus/plus.js'),{registerQuestsTab}=await import('/plus/tabs/quests.js'),{hooks}=await import('/plus/hooks.js'),{refKey,textRefs}=await import('/plus/quests/table.js');
 const plus=mountPlus();await plus.ready;await plus.setSetting('original',false);
 const tracker=registerQuestsTab(plus);await tracker.ready;plus.selectTab('quests');
 const byText=new Map();for(const r of textRefs()){const t=tracker.log.texts.get(refKey(r));if(t)byText.set(t,refKey(r));}
 const rec=window.__quests={trace:[],events:[],texts:0,tracker,plus};
 hooks.on('flagSet',p=>{if(p.region===0&&p.addr>=0x4A20&&p.addr<0x4B00)rec.events.push({flag:p.addr,value:p.value});});
 hooks.on('textPrinted',p=>{rec.texts++;const pos=hooks.state.position()||{};const ref=byText.get(p.text);if(ref)rec.events.push({text:ref,dataSet:pos.dataset,block:pos.block});});
 tracker.onChange((changes,cause)=>{const li=id=>document.querySelector(`#por-plus-content li[data-quest="${id}"]`)?.dataset.status||null;
  rec.trace.push({cause,textEvent:rec.texts+1,changes:changes.map(c=>[c.id,c.from,c.to]),tab:changes.map(c=>li(c.id))});});
 const met=tracker.log.list().filter(q=>q.met).map(q=>q.id);
 if(tracker.log.texts.size!==new Set(textRefs().map(refKey)).size||met.length)console.error('QUESTS FAIL install',tracker.log.texts.size,met);
 return {texts:tracker.log.texts.size,met,slot:tracker.slot,shown:document.getElementById('por-plus-content').textContent.slice(0,80)};
})()

(async()=>{
 const rec=window.__quests,{tracker}=rec,{refKey}=await import('/plus/quests/table.js');
 const t=rec.trace.find(e=>e.changes.some(c=>c[0]==='slums'));
 const want=tracker.log.texts.get('3:8:A8B6'),ev=rec.events.filter(e=>e.text).at(-1);
 const ok=t&&t.cause==='textPrinted'&&t.changes.length===1&&t.changes[0][2]==='offered'&&t.tab[0]==='offered'&&ev&&ev.text==='3:8:A8B6'&&rec.texts===t.textEvent;
 if(!ok)console.error('QUESTS FAIL offer',JSON.stringify(t),JSON.stringify(ev),rec.texts);
